    public const string StateId="finale";
    public static readonly ImmutableArray<string> MainQuests=["Q-F01","Q-F02","Q-F03","Q-F04","Q-F05"];
    private readonly IAdventureRepository _repository;private readonly RuntimeCatalog _catalog;private readonly IEndingCheckpointArchive? _checkpoints;private readonly Dictionary<Guid,CommitPlanCommand> _previews=[];
    public FinalePackage Package {get;}
    public ImmutableDictionary<string,SceneGeometry> Geometry {get;}
    public FinalReadinessService FinalReadiness {get;}
    public FinaleService(IAdventureRepository repository,RuntimeCatalog catalog,FinalePackage package,IEndingCheckpointArchive? checkpoints=null){FinalePackage.Validate(package);_repository=repository;_catalog=catalog;_checkpoints=checkpoints;Package=package;Geometry=package.Scenes.ToImmutableDictionary(s=>s.Geometry.Id,s=>s.Geometry);FinalReadiness=new(repository,catalog,checkpoints);}
    private static void Require(bool yes,string reason){if(!yes)throw new InvalidOperationException(reason);}
    private static ActorState Actor(BranchSnapshot s)=>BranchOperations.Read<ActorState>(s,"actor")??throw new InvalidOperationException("角色真实位置缺失。");
    private FinaleState State(BranchSnapshot s)=>BranchOperations.Read<FinaleState>(s,StateId) is{} st&&st.ContentVersion==Package.Version?st:throw new InvalidOperationException("终章候选尚未按实际出发初始化，或内容版本不符。");
    private static QuestState? Quest(BranchSnapshot s,string id)=>BranchOperations.Read<QuestState>(s,"quest:"+id);
    private static bool Closed(BranchSnapshot s,string id)
    {if(Quest(s,id) is not{Lifecycle:QuestLifecycle.Closed,Outcome:QuestOutcome.Completed} quest)return false;var r=s.Receipts.SingleOrDefault(r=>r.SemanticKey==id+":resolution");if(r is null)return false;if(id=="Q-604")return r.ActionType=="network_finale_departure";if(id=="Q-F04")return r.ActionType=="final_policy_execution"&&BranchOperations.Read<FinalEndingSnapshot>(s,"final:ending") is{} ending&&ending.QF04Instance==quest.Instance&&Same(StrictJson.Deserialize<FinalEndingSnapshot>(r.ResultJson),ending);if(r.ActionType!="main_quest_resolution")return false;var actual=StrictJson.Deserialize<MainQuestResolution>(r.ResultJson);return actual.Quest==id&&actual.Instance==quest.Instance&&actual.Outcome=="completed";}
    private static bool Same<T>(T a,T b)=>StrictJson.Serialize(a)==StrictJson.Serialize(b);
    private EntityChange Change(BranchSnapshot s,FinaleState st)=>BranchOperations.Change(s,StateId,"finale_state",st);
    private static bool Result(BranchSnapshot s,string id)=>BranchOperations.Read<FinaleEncounterResult>(s,"RF:result:"+id) is{Completed:true} result&&s.Receipts.Any(r=>r.SemanticKey=="RF:"+id+":result"&&r.ActionType=="finale_encounter_result"&&Same(StrictJson.Deserialize<FinaleEncounterResult>(r.ResultJson),result));
    private string[] Reads(BranchSnapshot s)=>s.Entities.Select(e=>e.Id).Concat(new[]{StateId,"actor","ship:glimmer","final:actual-departure","final:preparation","final:commitments","final:central-safety","final:control-access","final:ending"}).Concat(MainQuests.SelectMany(q=>new[]{"quest:"+q,"proposal:"+q})).Distinct(StringComparer.Ordinal).ToArray();
    private async ValueTask<CommandResult> Execute(CommitPlanCommand command)
    {var current=_repository.Session;if(command.Context.Profile!=current.Profile||command.Context.Branch!=current.Branch||command.Context.Load!=current.Load||command.Context.ReleaseId!=current.ReleaseId)return new(CommitStatus.Rejected,null,[new("stale_load",StateId,"档案、分支、读取世代或内容发布已改变，请重新预览。")]);if(_repository is not IEventLeaseStore lease)throw new InvalidOperationException("终章前景需要原子占用接口。");string owner="finale:"+command.Context.Command.Value;Require(await lease.TryLeasesAsync(command.Context.Load,owner,["input:foreground"]),"其他前景工作尚未交接。");try{return await _repository.ExecuteAsync(command);}finally{await lease.ReleaseLeasesAsync(command.Context.Load,owner);}}
    private ValueTask<CommandResult> Commit(BranchSnapshot s,string action,ImmutableArray<EntityChange> changes,object result,string? key=null,ImmutableArray<ItemChange> items=default,ImmutableArray<BalanceChange> balances=default,DraftStamp? draft=null)=>Execute(BranchOperations.Plan(_repository,s,key??"RF:action:"+Guid.NewGuid(),action,GateChanges(s,changes),Reads(s),result,items,balances,draft:draft));
    private static void Safe(BranchSnapshot s){BranchOperations.Safe(s);Require(!s.Entities.Where(e=>e.Kind=="event").Select(e=>StrictJson.Deserialize<EventSession>(e.Json)).Any(e=>e.State==EventLifecycle.Running),"当前事件尚未交接。");Require(!s.Entities.Where(e=>e.Kind=="transport_segment").Select(e=>StrictJson.Deserialize<TransportSegment>(e.Json)).Any(e=>e.CargoInTransit&&!e.Completed),"实际运输尚未交接。");}
    private async ValueTask<FinaleDeparture> ActualDeparture(BranchSnapshot s)
    {
        Require(Closed(s,"Q-604"),"需要真实起航并关闭Q604。");var receipt=s.Receipts.SingleOrDefault(r=>r.SemanticKey=="Q-604:resolution"&&r.ActionType=="network_finale_departure")??throw new InvalidOperationException("实际终章出发生产回执缺失。");var departure=StrictJson.Deserialize<FinaleDeparture>(receipt.ResultJson);var actual=BranchOperations.Read<FinaleDeparture>(s,"final:actual-departure");var frozen=BranchOperations.Read<FrozenPreparation>(s,"final:preparation");Require(actual is not null&&Same(actual,departure)&&frozen is not null,"实际出发实体及封存准备不符。");
        Require(departure.SourceRegion=="R6"&&departure.Destination=="RF"&&departure.SourceBerthScene=="R6-S01"&&departure.DestinationScene=="RF-S01"&&departure.Landing==FinalePackage.LandingStand&&departure.DestinationGeometrySha256==Package.GeometrySha256("RF-S01")&&departure.Q604Instance==Quest(s,"Q-604")!.Instance&&departure.PreparationId==frozen!.Id&&departure.Q604Instance==frozen.Q604Instance&&departure.PreFinalCheckpoint==frozen.PreFinalCheckpoint&&departure.VesselInstance==frozen.VesselInstance,"出发实例、范围、真实落点或几何来源不符。");
        var seal=s.Receipts.SingleOrDefault(r=>r.SemanticKey=="Q-604:preparation-sealed"&&r.ActionType=="seal_final_preparation");Require(seal is not null&&Same(StrictJson.Deserialize<FrozenPreparation>(seal.ResultJson),frozen)&&departure.SourceReceipts.Contains(seal.ReceiptId),"原封存准备回执未随实际出发保留。");
        var ship=BranchOperations.Read<SharedVessel>(s,"ship:glimmer");var original=s.Receipts.SingleOrDefault(r=>r.SemanticKey=="Q-104:resolution"&&r.ActionType=="tidegate_vessel_handover");Require(ship is not null&&original is not null&&ship.Instance==departure.VesselInstance&&ship.DockRegion=="RF"&&ship.WatchOfficer=="N-DECKWATCH"&&s.Entities.Count(e=>e.Kind=="shared_vessel")==1,"必须是原移交唯一微光号实际在RF停泊。");var hand=StrictJson.Deserialize<TidegateHandover>(original!.ResultJson);Require(hand.VesselInstance==ship!.Instance.ToString()&&hand.VesselDefinition=="GLIMMER"&&departure.SourceReceipts.Contains(original.ReceiptId),"出发船与原Q104实体移交不符。");
        var berth=BranchOperations.Read<VesselBerth>(s,"berth:R6");Require(berth is not null&&berth.Instance==ship.Instance&&berth.Region=="R6"&&berth.Scene==departure.SourceBerthScene&&berth.Boarding==departure.SourceBoarding&&berth.AuthorityReceipt==departure.SourceBerthReceipt&&departure.SourceReceipts.Contains(berth.AuthorityReceipt),"原R6泊位来源或站位不符。");BranchOperations.Evidence(s,departure.SourceBerthReceipt,"vessel_berth_verified");
        var risk=BranchOperations.Read<CurrentRiskRegister>(s,"final:commitments");Require(risk is not null&&risk.SourceReceipt==departure.RiskRegisterReceipt&&departure.SourceReceipts.Contains(risk.SourceReceipt),"实际出发风险登记来源缺失。");BranchOperations.Evidence(s,risk!.SourceReceipt,"high_risk_register_verified");Require(departure.SourceReceipts.All(id=>s.Receipts.Any(r=>r.ReceiptId==id)),"出发来源列表含尚未产生的回执。");
        var checkpoints=_checkpoints??throw new InvalidOperationException("需要真实受保护存档查询接口。");var verifiedFrozen=frozen??throw new InvalidOperationException("原封存准备缺失。");var checkpoint=await checkpoints.FindAsync(departure.PreFinalCheckpoint);Require(checkpoint is not null&&checkpoint.Profile==_repository.Session.Profile&&checkpoint.SourceBranch==verifiedFrozen.SourceBranch&&checkpoint.Release==verifiedFrozen.Release,"原真实终局前检查点不可用。");Require(Actor(s).Scene==departure.DestinationScene&&Actor(s).Position==departure.Landing&&new NavigationGrid(Geometry[departure.DestinationScene]).CanStand(departure.Landing,true),"需要实际RF安全登陆，不能只写角色场景。");return departure;
    }
    public async ValueTask InitializeRegionAsync()
    {var s=await _repository.SnapshotAsync();if(BranchOperations.Entity(s,StateId) is not null){State(s);return;}Safe(s);var actual=await ActualDeparture(s);var changes=ImmutableArray.CreateBuilder<EntityChange>();changes.Add(Change(s,new(){ContentVersion=Package.Version}));foreach(string id in MainQuests){Require(BranchOperations.Entity(s,"quest:"+id) is null,"终章任务不能覆盖已存结果。");changes.Add(BranchOperations.Change(s,"quest:"+id,"quest",new QuestState(id,Guid.NewGuid(),id=="Q-F01"?QuestLifecycle.Active:QuestLifecycle.Unaccepted,null)));}var committed=await Commit(s,"finale_actual_arrival_registered",changes.ToImmutable(),new{source_q604_instance=actual.Q604Instance,preparation=actual.PreparationId,no_material_grant=true,no_seed_reward=true},"RF:initialize:"+Package.Version);Require(committed.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,"真实终章入场未提交。");}
    private static bool LayerReady(FinaleState st)=>st.LayerLeftIsolated&&st.LayerRightIsolated&&st.LayerCheckRevision==st.LayerRevision;
    private ImmutableArray<EntityChange> GateChanges(BranchSnapshot s,ImmutableArray<EntityChange> changes)
    {var c=changes.SingleOrDefault(x=>x.Id==StateId);var st=c is null?BranchOperations.Read<FinaleState>(s,StateId):StrictJson.Deserialize<FinaleState>(c.Json);if(st is null)return changes;bool Has(string id)=>Result(s,id)||changes.Any(c=>c.Id=="RF:result:"+id&&StrictJson.Deserialize<FinaleEncounterResult>(c.Json).Completed);bool SafeCore=Has("ENC-RF-04");var values=new Dictionary<string,bool>{{"formal_recognised",st.FormalRecognised},{"basic_maintenance",true},{"formal_released",st.FormalReleased},{"shaft_safe",st.ShaftHandle&&st.ShaftIsolated&&st.ShaftCheckRevision==st.ShaftRevision&&Has("ENC-RF-01")},{"command_released",st.RookCustody&&st.CommandChainReleased&&st.RunningLoopChecked},{"current_isolation",LayerReady(st)||st.MachineHallEntered},{"central_stable",SafeCore}};var output=changes.ToBuilder();foreach(var (name,allowed) in values){string id="RF:gate:"+name;var old=BranchOperations.Read<FinaleGate>(s,id);if(old is null||old.Allowed!=allowed)output.Add(BranchOperations.Change(s,id,"chapter_gate",new FinaleGate(name,allowed,Package.Version)));}return output.ToImmutable();}
    public ImmutableDictionary<string,SceneGeometry> CurrentGeometry(BranchSnapshot s)=>Package.Scenes.ToImmutableDictionary(x=>x.Geometry.Id,x=>x.Geometry with{Danger=x.Hazards.Where(h=>!Result(s,h.Id.Split('.')[0])).Select(h=>h.Area).ToImmutableArray()});
    public async ValueTask<ImmutableDictionary<string,SceneGeometry>> CurrentGeometryAsync()=>CurrentGeometry(await _repository.SnapshotAsync());
    private void At(BranchSnapshot s,string spot){var actor=Actor(s);Require(CurrentGeometry(s).TryGetValue(actor.Scene,out var scene)&&scene.Spots.Any(p=>p.Id==spot&&p.Stand.Distance(actor.Position)<=2.5)&&new NavigationGrid(scene).CanStand(actor.Position,true),"请先走到当前真实安全操作站位。");}
    private bool Acquired(BranchSnapshot s,ChapterMaterial m)=>BranchOperations.Read<ChapterMaterialAccess>(s,"material:"+m.Id) is{} access&&access.Id==m.Id&&access.Version==m.Version&&access.TranslationVersion==m.TranslationVersion&&access.Fingerprint==m.Fingerprint&&access.SourceRoot==m.SourceRoot;
    private bool Accessible(BranchSnapshot s,ChapterMaterial m)=>m.AccessClass=="public"&&(m.Quest switch{"Q-F01"=>true,"Q-F02"=>Closed(s,"Q-F01"),"Q-F03"=>Closed(s,"Q-F02"),"Q-F04"=>Closed(s,"Q-F03"),"Q-F05"=>Closed(s,"Q-F04")&&BranchOperations.Entity(s,"final:ending") is not null,_=>false});
    private bool Sources(BranchSnapshot s,params string[] ids)=>ids.All(id=>Package.Materials.SingleOrDefault(m=>m.Id==id) is{} m&&Acquired(s,m)&&Accessible(s,m));
    public async ValueTask<FinaleView> ViewAsync(){var s=await _repository.SnapshotAsync();var actor=Actor(s);return new(s,actor,State(s),MainQuests.Select(q=>Quest(s,q)!).ToImmutableArray(),Package.Materials.Where(m=>Acquired(s,m)&&Accessible(s,m)).ToImmutableArray(),Package.Stations.Where(st=>st.Spot.StartsWith(actor.Scene+'.',StringComparison.Ordinal)).ToImmutableArray(),CurrentGeometry(s));}
    public async ValueTask TraverseAsync(ImmutableArray<Point2> path){if(path.IsDefaultOrEmpty)return;var s=await _repository.SnapshotAsync();Safe(s);var actor=Actor(s);var nav=new NavigationGrid(CurrentGeometry(s)[actor.Scene]);var from=actor.Position;foreach(var to in path){Require(nav.SegmentClear(from,to,true),"真实路径穿过障碍或尚未处置危险。");from=to;}var result=await Commit(s,"finale_walk",[BranchOperations.Change(s,"actor","actor",actor with{Position=from,ActionClock=checked(actor.ActionClock+1)})],new{actual_path=path});Require(result.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,"状态变化，实际移动未提交。");}
    public async ValueTask MoveAsync(Point2 point)=>await TraverseAsync([point]);
    public string? PortIssue(BranchSnapshot s,Port port)
    {var actor=Actor(s);if(!Geometry.TryGetValue(actor.Scene,out var scene)||!scene.Ports.Any(p=>p.Id==port.Id))return "出口不在当前实际场景。";var st=State(s);if(port.TargetScene=="RF-S06"&&!LayerReady(st))return "重新进入机组厅需要当前继电隔离核验。";if(port.TargetScene=="RF-S05"&&actor.Scene=="RF-S04"&&!Closed(s,"Q-F02"))return "实际接管摘要尚未交接。";if(port.TargetScene=="RF-S07"&&!Closed(s,"Q-F03"))return "实际稳定检修记录尚未交接。";string gate="RF:gate:"+Package.PortGates[port.Id];return BranchOperations.Read<FinaleGate>(s,gate) is{Allowed:true,ContentVersion:var v}&&v==Package.Version?null:"本出口的实际现场条件未成立。";}
    public async ValueTask<CommandResult> EnterPortAsync(string id)
    {var s=await _repository.SnapshotAsync();Safe(s);var actor=Actor(s);var geometry=CurrentGeometry(s);var port=geometry[actor.Scene].Ports.Single(p=>p.Id==id);AtPort();void AtPort()=>Require(actor.Position.Distance(port.Stand)<=2.5,"请先走到实际配对出口。");Require(PortIssue(s,port) is null,PortIssue(s,port)??"");var pair=geometry[port.TargetScene].Ports.Single(p=>p.Id==port.TargetPort);Require(new NavigationGrid(geometry[actor.Scene]).CanStand(actor.Position,true)&&new NavigationGrid(geometry[port.TargetScene]).CanStand(pair.Stand,true),"实际两端入口危险。");var connection=_catalog.Connections.Single(c=>c.A==actor.Scene&&c.B==port.TargetScene||c.B==actor.Scene&&c.A==port.TargetScene);string gate="RF:gate:"+Package.PortGates[id],travel="travel-gate:"+TravelService.ConnectionKey(connection.A,connection.B);var reads=ImmutableArray.Create(new EntityStamp(gate,BranchOperations.Entity(s,gate)!.Revision));var old=BranchOperations.Read<ConnectionSafetyState>(s,travel);if(old is null||!old.Dependencies.SequenceEqual(reads)){var issued=await Commit(s,"connection_safety_verified",[],new ConnectionSafetyState(connection.A,connection.B,TravelService.Contract(connection),true,true,reads,""));Require(issued.Status==CommitStatus.Committed&&issued.Receipt is not null,"实际出口安全证明未提交。");var registered=await new TravelService(_repository,_catalog,CurrentGeometry(await _repository.SnapshotAsync())).RegisterConnectionSafetyAsync(issued.Receipt!.Id.Value.ToString());Require(registered.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,"实际连接登记未提交。");s=await _repository.SnapshotAsync();actor=Actor(s);}
        var st=State(s);var changes=ImmutableArray.CreateBuilder<EntityChange>();if(port.TargetScene=="RF-S04"&&actor.Scene is "RF-S02" or "RF-S03")changes.Add(Change(s,st with{ActualApproach=actor.Scene=="RF-S02"?"formal":"maintenance"}));if(port.TargetScene=="RF-S06"&&!st.MachineHallEntered)changes.Add(Change(s,st with{MachineHallEntered=true}));var proof=new TraversedConnection(actor.Scene,port.TargetScene,port.Id,pair.Id,port.Stand,pair.Stand,checked(actor.ActionClock+1),TravelService.Contract(connection),reads.Add(new(travel,BranchOperations.Entity(s,travel)!.Revision)),true);changes.Add(BranchOperations.Change(s,"actor","actor",actor with{Scene=port.TargetScene,Position=pair.Stand,ActionClock=proof.ActionClock}));return await Commit(s,"scene_transition",changes.ToImmutable(),proof);}
    public async ValueTask<CommandResult> DiscoverAsync(string id){var s=await _repository.SnapshotAsync();Safe(s);var m=Package.Materials.Single(x=>x.Id==id);At(s,m.Spot);Require(Accessible(s,m),"该材料当前具体阶段未获准。");if(Acquired(s,m))return new(CommitStatus.AlreadyCommitted,null,[]);return await Commit(s,"finale_material_acquired",[BranchOperations.Change(s,"material:"+id,"material_access",new ChapterMaterialAccess(id,m.Version,m.TranslationVersion,m.Fingerprint,m.SourceRoot,m.Spot))],new{material=id,source_root=m.SourceRoot,source_channel=m.Kind=="listening_script"?"written_transcript_only":"written_original",audio_listened=false},"material:"+id+":acquired");}
    public async ValueTask<ChapterMaterial> OpenMaterialAsync(string id)=>(await ViewAsync()).Materials.SingleOrDefault(m=>m.Id==id)??throw new InvalidOperationException("只有实际取得且当前获准的只读材料可查看。");
    public async ValueTask<DraftSaved> SaveDraftAsync(string task,long expectedRevision,DraftId? draft,string body){Require(Package.WritingTasks.Any(t=>t.Id==task),"未登记终章短写作。");var ss=_repository.Session;return await _repository.SaveAsync(new(ss.Profile,ss.Branch,ss.Load,task,draft,expectedRevision,body,Package.Version));}
    public ValueTask<CommandResult> ConfirmPreviewAsync(Guid token)=>_previews.TryGetValue(token,out var command)?Execute(command):FinalReadiness.ConfirmAsync(token);
    public void ClosePreview(Guid token){_previews.Remove(token);FinalReadiness.ClosePreview(token);}
